\begin{aligned}
\operatorname{RealizesTuple}_{L,n}(\mathfrak A,\bar a,\Sigma)
&\leftrightarrow\forall\varphi\in\Sigma\;(\mathfrak A\models\varphi[\bar a]),\\
\operatorname{Realizes}_{L,n}(\mathfrak A,\Sigma)
&\leftrightarrow\exists\bar a\in|\mathfrak A|^n\;
\operatorname{RealizesTuple}_{L,n}(\mathfrak A,\bar a,\Sigma),\\
\operatorname{Omits}_{L,n}(\mathfrak A,\Sigma)
&\leftrightarrow\neg\operatorname{Realizes}_{L,n}(\mathfrak A,\Sigma).
\end{aligned}
